fn element_wise_modulo(a: Vec<i32>, b: Vec<i32>) -> Vec<i32> {
    // Create a new vector to store the results
    let mut result = Vec::with_capacity(a.len());

    // Iterate over the elements of the input arrays
    for (x, y) in a.iter().zip(b.iter()) {
        // Calculate the remainder and push it to the result vector
        result.push(x % y);
    }

    // Return the result vector
    result
}

fn main() {
    // Example usage
    let a = vec![10, 20, 30];
    let b = vec![3, 7, 5];
    let result = element_wise_modulo(a, b);
    println!("{:?}", result); // Output: [1, 6, 0]
}